def transform(grid):
    out = [[9]*9 for _ in range(5)]
    for r in range(len(grid)):
        if r in (14,19,24):
            oi = (r-4)//5
            for c,v in enumerate(grid[r]):
                if v not in (0,9):
                    oj = (c-2)//3
                    if 0 <= oj < 9: out[oi][oj] = v
    return out
